        WeightedGraph graph = new WeightedGraph(vertices);

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int idx = i * cols + j;

                if (j + 1 < cols) {
                    graph.addWeightedEdge(idx, idx + 1, 1.0);
                }
                if (i + 1 < rows) {
                    graph.addWeightedEdge(idx, idx + cols, 1.0);
                }
            }
        }

        return graph;
    }
}

